import React, { useState } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const QuanLyHoaDon = () => {
    const now = new Date();
    const currentMonth = now.getMonth() + 1;
    const currentYear = now.getFullYear();

    const [selectedMonth, setSelectedMonth] = useState(currentMonth);
    const [selectedYear, setSelectedYear] = useState(currentYear);

    const years = [2024, 2025, 2026];
    const months = Array.from({ length: 12 }, (_, i) => i + 1);

    const allRooms = [];
    for (let floor = 1; floor <= 9; floor++) {
        for (let num = 1; num <= 5; num++) {
            allRooms.push(`${floor}0${num}`);
        }
    }

    const isCurrentOrFuture = selectedYear > currentYear || (selectedYear === currentYear && selectedMonth >= currentMonth);
    const totalReceived = isCurrentOrFuture ? 0 : (5000000 * 45);

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden'
        }} className="glass-card">

            {/* HEADER - Theo chuẩn trang Cư dân */}
            <div style={{ padding: '20px', color: '#fff', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <h2 style={{ margin: 0, textShadow: '1px 1px 4px rgba(0,0,0,0.5)' }}>Quản lý hoá đơn</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select 
                        value={selectedMonth} 
                        onChange={(e) => setSelectedMonth(parseInt(e.target.value))}
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}
                    >
                        {months.map(m => <option key={m} value={m}>Tháng {m}</option>)}
                    </select>
                    <select 
                        value={selectedYear} 
                        onChange={(e) => setSelectedYear(parseInt(e.target.value))}
                        style={{ padding: '8px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' }}
                    >
                        {years.map(y => <option key={y} value={y}>Năm {y}</option>)}
                    </select>
                </div>
            </div>

            <div style={{ flex: 1, padding: '0 20px 20px 20px', display: 'flex', gap: '30px', overflow: 'hidden' }}>

                {/* CỘT TRÁI: DANH SÁCH PHÒNG - Giữ nguyên style chuẩn */}
                <div style={{ 
                    width: '210px', 
                    display: 'grid', 
                    gridTemplateColumns: 'repeat(5, 1fr)', 
                    gap: '6px', 
                    alignContent: 'flex-start', 
                    overflowY: 'auto',
                    padding: '12px',
                    backgroundColor: 'rgba(255,255,255,0.1)',
                    borderRadius: '20px',
                    border: '1px solid rgba(255,255,255,0.1)'
                }}>
                    {allRooms.map(room => (
                        <div key={room} style={{ 
                            background: !isCurrentOrFuture ? 'rgba(255,255,255,0.8)' : '#ffcc00', 
                            color: '#333', padding: '8px 0', borderRadius: '8px', 
                            textAlign: 'center', fontSize: '11px', fontWeight: 'bold',
                            border: '1px solid rgba(0,0,0,0.05)'
                        }}>
                            {room}
                        </div>
                    ))}
                </div>

                {/* CỘT PHẢI: CHI TIẾT - Ép khung trắng cố định */}
                <div style={{ 
                    flex: 1, 
                    backgroundColor: '#ffffff', 
                    borderRadius: '25px', 
                    padding: '30px',
                    display: 'flex',
                    flexDirection: 'column',
                    color: '#000',
                    boxShadow: '0 8px 32px 0 rgba(0, 0, 0, 0.3)',
                    overflow: 'hidden' // Khóa không cho nội dung đẩy khung
                }}>
                    {/* Phần tổng tiền (Header của khung chi tiết) */}
                    <div style={{ 
                        marginBottom: '20px', padding: '20px', backgroundColor: '#f8f9fa', 
                        borderRadius: '15px', borderLeft: '8px solid #8b5e5e', flexShrink: 0
                    }}>
                        <div style={{ fontSize: '16px', fontWeight: 'bold', color: '#555' }}>
                            Tổng tiền đã nhận tháng {selectedMonth}/{selectedYear}:
                        </div>
                        <div style={{ fontSize: '36px', fontWeight: '800', color: totalReceived > 0 ? '#28a745' : '#ccc', marginTop: '5px' }}>
                            {totalReceived.toLocaleString()}đ
                        </div>
                    </div>

                    <h3 style={{ borderBottom: '2px solid #eee', paddingBottom: '10px', marginBottom: '10px', flexShrink: 0 }}>
                        Lịch sử giao dịch
                    </h3>

                    {/* KHUNG CUỘN CHAT (Scrollable Area) */}
                    <div style={{ 
                        flex: 1, 
                        overflowY: 'auto', // Cho phép cuộn bên trong
                        minHeight: 0,      // Ép flexbox không vỡ form
                        paddingRight: '5px'
                    }}>
                        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                            <thead style={{ position: 'sticky', top: 0, backgroundColor: '#fff', zIndex: 1 }}>
                                <tr style={{ textAlign: 'left', color: '#888', fontSize: '13px' }}>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Phòng</th>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Số tiền</th>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Nội dung</th>
                                    <th style={{ padding: '12px', borderBottom: '2px solid #f1f1f1' }}>Thời gian</th>
                                </tr>
                            </thead>
                            <tbody>
                                {!isCurrentOrFuture ? (
                                    allRooms.map(room => (
                                        <tr key={room} style={{ borderBottom: '1px solid #f9f9f9' }}>
                                            <td style={{ padding: '12px', fontWeight: 'bold' }}>{room}</td>
                                            <td style={{ padding: '12px', color: '#28a745', fontWeight: '600' }}>5,000,000đ</td>
                                            <td style={{ padding: '12px', fontSize: '13px' }}>Tiền phòng T{selectedMonth}</td>
                                            <td style={{ padding: '12px', fontSize: '11px', color: '#999' }}>01/{selectedMonth}/{selectedYear}</td>
                                        </tr>
                                    ))
                                ) : (
                                    <tr>
                                        <td colSpan="4" style={{ textAlign: 'center', padding: '100px 0', color: '#ccc', fontStyle: 'italic' }}>
                                            Chưa có dữ liệu giao dịch...
                                        </td>
                                    </tr>
                                )}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default QuanLyHoaDon;
